  .nav-link {
    padding: 0.75rem 1rem;
    font-size: 1rem;
  }

  .nav-dropdown-menu {
    position: static;
    opacity: 1;
    visibility: visible;
    transform: none;
    box-shadow: none;
    border: none;
    background: rgba(255, 255, 255, 0.03);
    border-radius: var(--radius-md);
    margin-top: 0.25rem;
    display: none;
  }

  .nav-dropdown.open .nav-dropdown-menu {
    display: block;
  }

  .nav-toggle {
    display: flex;
  }

  .hero {
    padding: calc(var(--nav-height) + 2rem) 0 2.5rem;
  }

  .hero-title {
    font-size: 2rem;
  }

  .use-cases-grid {
    grid-template-columns: 1fr;
  }

  .stats-row {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .diagram-container {
    flex-direction: column;
    align-items: center;
  }

  .diagram-pillar {
    max-width: 100%;
  }

  .featured-banner {
    flex-direction: column;
    text-align: center;
    padding: 2rem;
  }

  .form-row {
    grid-template-columns: 1fr;
  }

  .support-grid {
    grid-template-columns: 1fr;
  }

  .benefits-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }

  .cookie-inner {
    flex-direction: column;
    text-align: center;
  }

  .timeline-item {
    flex-direction: column;
    gap: 0.5rem;
  }

  .timeline-duration {
    text-align: left;
    min-width: auto;
  }

  .section {
    padding: 3rem 0;
  }
}

@media (max-width: 480px) {
  .hero-title {
    font-size: 1.75rem;
  }

  .hero-actions {
    flex-direction: column;
  }

  .hero-actions .btn-primary,
  .hero-actions .btn-secondary {
    width: 100%;
    justify-content: center;
  }
}

