      wrapper.addEventListener('mouseenter', () => clearInterval(autoPlay));
      wrapper.addEventListener('mouseleave', () => {
        autoPlay = setInterval(() => {
          goToSlide((currentSlide + 1) % totalSlides);
        }, 6000);
      });
    }
  }

